clearScene();setBig(null);
setEq("$$V^*=(31.82,\\,36.67,\\,44.81,\\,54.77,\\,66.94,\\,81.82,\\,100.00)$$","top");
lamps({y:320,gap:340,items:[
  {label:"策略迭代",sub:"评估到底再贪心",state:"on"},
  {label:"值迭代",sub:"每轮取一次 max",state:"on"}]});
setCap("两条路通向同一个 V*，每轮都在做「评估 + 贪心」。<b>那中途手里拿的是同一种东西吗？</b>");

clearScene();setEq(null);
setBig("V_k 是第 k 轮贪心策略的值","算法一边改进策略，一边把它的值算准");
setCap("这个模型让「V_k 对应哪个策略」成为一个有答案的问题。<b>它没有。</b>下面用真实数字检验。");

clearScene();setBig(null);
setEq("$$\\text{PI: } (\\pi_i,\\,V^{\\pi_i}) \\qquad\\qquad \\text{VI: } V_k$$","top");
lamps({y:320,gap:340,items:[
  {label:"PI 手里",sub:"策略 + 它的准确值",state:"on"},
  {label:"VI 手里",sub:"只有一个数组",state:"on"}]});
setCap("PI 每轮内部解一次完整线性方程组，所以一轮很贵；VI 的贪心策略是<b>事后读出来的</b>，不是它维护的对象。");

clearScene();setBig(null);
setEq("$$\\text{VI 第 2 轮：} V_2 \\qquad \\text{贪心读出 } \\pi=\\leftarrow\\leftarrow\\leftarrow\\leftarrow\\rightarrow\\rightarrow\\rightarrow$$","top");
bars({vals:[1.90,0.45,0.00,0.00,0.00,4.50,19.00],
  x:210,y:430,w:860,h:170,max:100,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return "b";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>VI 的 V₂</b> 几乎还贴着地面：中间三个精确为 0，最大的 s₇ 也只有 19.00。<b>记住这个策略。</b>");

clearScene();setBig(null);
setEq("$$\\text{同一个策略 } \\leftarrow\\leftarrow\\leftarrow\\leftarrow\\rightarrow\\rightarrow\\rightarrow \\text{ 的精确值函数}$$","top");
morphBars({from:[1.90,0.45,0.00,0.00,0.00,4.50,19.00],
  to:[10.00,8.18,6.69,5.48,66.94,81.82,100.00],
  x:210,y:374,w:860,h:150,max:100,dur:1700,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i>=4?"g":"y";},
  fmt:function(v){return v.toFixed(2);}});
setCap("左边是 VI 手里的 V₂，右边是<b>同一个策略</b>真正的值函数。数字差了一个量级 —— <b>V₂ 不是任何策略的值函数</b>。");

clearScene();setBig(null);
setEq("$$V_k(s)\\;=\\;\\max_{\\pi}\\;\\mathbb{E}_{\\pi}\\Big[\\sum_{t=0}^{k-1}\\gamma^t r_t \\;\\Big|\\; s_0=s\\Big]$$","top");
note("k 步时域的最优值",640,320,"g lg");
note("最优 —— 对另一个问题",640,380,"y lg");
setCap("V₂ 那么小是因为<b>只走 2 步根本够不到 +10</b>。<b>披露</b>：约 01:07:34 只作断言，对 k 的归纳没做，有限时域那节整节跳过。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"PI 手里",sub:"准确但不够好",state:"on"},
  {label:"VI 手里",sub:"够好但不准确",state:"on"}]});
note("轮数不可直接比",640,420,"sm");
setCap("<b>指名反驳</b>：本例 PI 6 轮终止但每轮含完整评估；VI 的贪心策略第 11 轮才最优，而值还差得远。");

clearScene();
setEq("$$V_{k+1}(s)\\;\\leftarrow\\;\\max_a\\Big[\\,R(s,a)+\\gamma\\sum_{s'}P(s'\\mid s,a)V_k(s')\\,\\Big]$$","top");
mdpChain({n:5,x:280,y:372,gap:180,r:30,
  label:function(i){return i<4?("V"+i):"…";},
  cls:function(i){return i===0?"b":"v";},
  arcs:[[0,1,"B","y"],[1,2,"B","y"],[2,3,"B","y"],[3,4,"B","y"]]});
setCap("值迭代 = 把同一个算子 <b>B</b> 反复套用在它自己的输出上。");

clearScene();setEq(null);
lamps({y:250,r:36,gap:440,items:[
  {label:"一定会停吗？",sub:"更新何时小于 ε",state:"off"},
  {label:"停在同一处吗？",sub:"换个 V₀ 还一样吗",state:"off"}]});
setCap("两个问题必须一起回答：<b>会停吗？停在同一处吗？</b>");

clearScene();setEq(null);
setBig("因为更新越来越小","所以它一定会收敛 · 你每跑一遍，确实都看到它一轮比一轮小");
setCap("这是你很可能持有的模型。<b>它听上去像一个理由。</b>");

clearScene();setEq(null);
note("更新幅度变小",420,300,"r");
note("算法收敛",860,300,"r");
arrow(520,282,760,282,"r",-34);
arrow(760,322,520,322,"r",-34);
note("互为理由",640,392,"y");
setCap("<b>循环论证</b>：它会收敛，因为它在收敛。");

clearScene();
setEq("$$\\lVert BV - BV' \\rVert_\\infty \\;\\le\\; \\gamma\\,\\lVert V - V' \\rVert_\\infty \\qquad (\\gamma<1)$$","top");
tree({r:22,nodes:[
  {id:"a",x:380,y:250,label:"V",cls:"b"},
  {id:"b",x:380,y:430,label:"V′",cls:"b"},
  {id:"c",parent:"a",x:900,y:310,label:"BV",cls:"g"},
  {id:"d",parent:"b",x:900,y:370,label:"BV′",cls:"g"}]});
arrow(348,272,348,408,"sm");
note("距离 d",334,345,"y","end");
note("≤ γ·d",962,344,"g","start");
note("套用一次 B",640,252,"sm");
setCap("<b>γ-压缩</b>：算子把<b>任意两点</b>之间的距离，一次至少缩到 γ 倍。");

clearScene();setEq(null);
tree({r:20,nodes:[
  {id:"s1",x:250,y:300,label:"①",sub:"max 之差",cls:"y"},
  {id:"s2",parent:"s1",x:510,y:300,label:"②",sub:"R 相消",cls:"y"},
  {id:"s3",parent:"s2",x:770,y:300,label:"③",sub:"提到和外",cls:"y"},
  {id:"s4",parent:"s3",x:1030,y:300,label:"④",sub:"ΣP = 1",cls:"g"}]});
note("→ γ‖V−V′‖",1030,392,"g");
setCap("四步只用了<b>概率和为 1</b> 与 <b>max 的次可加性</b> —— 没用 MDP 的任何结构。");

clearScene();
setEq("$$V^{(a)}_0=\\mathbf{0}\\qquad V^{(b)}_0=(50,-20,80,0,100,-50,30)$$","top");
fillBars({vals:[100.00,45.00,40.50,36.45,32.81,29.52,26.57,23.91],order:[0,1,2,3,4,5,6,7],step:330,
  x:210,y:430,w:860,h:170,max:100,
  label:function(i){return "k="+i;},
  cls:function(i){return i===0?"r":"v";},
  fmt:function(v){return v.toFixed(2);}});
setCap("柱高 = 两条轨迹之间的 sup 距离。<b>两个任意起点，各自套用 B。</b>");

clearScene();
setEq("$$BV^*=V^*\\;\\Longrightarrow\\;\\lVert V_k-V^*\\rVert_\\infty\\le\\gamma^k\\lVert V_0-V^*\\rVert_\\infty$$","top");
tree({r:24,nodes:[
  {id:"a",x:380,y:262,label:"V_k",cls:"b"},
  {id:"b",x:380,y:430,label:"V*",cls:"g"},
  {id:"c",parent:"a",x:900,y:322,label:"BV_k",cls:"v"},
  {id:"d",parent:"b",x:900,y:430,label:"V*",cls:"g"}]});
note("误差 ×γ",640,268,"y");
note("不动点，原地不动",640,404,"g");
setCap("把上一镜的 V′ 换成 <b>V* 本身</b> —— 两点的距离就变成<b>误差</b>。");

clearScene();setEq(null);
lamps({y:250,r:34,gap:330,items:[
  {label:"几何收敛",sub:"每轮误差乘 γ",state:"on"},
  {label:"不动点唯一",sub:"距离 ≤ γ 倍自身",state:"on"},
  {label:"与 V₀ 无关",sub:"V₀ 只进常数",state:"on"}]});
setCap("压缩 ⟹ 收敛 + 不动点唯一 + 与初值无关。<b>三个结论同一个来源。</b>");

clearScene();setEq(null);
lamps({y:250,r:34,gap:520,items:[
  {label:"非扩张",sub:"‖BV−BV′‖ ≤ ‖V−V′‖",state:"dead"},
  {label:"γ-压缩",sub:"‖BV−BV′‖ ≤ γ‖V−V′‖",state:"on"}]});
note("恒等映射就是它",380,392,"r");
note("唯一不动点 + 几何收敛",900,392,"g");
setCap("讲座口述的是左边，板上证的是右边。<b>差别不是措辞。</b>");

clearScene();setEq(null);
setBig("收敛来自 γ-压缩","不是「更新变小」· 那是结论，不是原因");
setCap("读到「压缩」就追问<b>模数是多少</b> —— 没有 γ&lt;1，后面全部不成立。");

clearScene();setBig(null);
setEq("$$\\text{while } \\lVert V_k - V_{k-1}\\rVert_\\infty > \\varepsilon:\\quad V_{k+1}\\leftarrow BV_k$$","top");
note("设 ε = 0.01 跑到满足",640,320,"sm lg");
note("此时离 V* 有多远",640,380,"y lg");
setCap("停机判据衡量的是<b>相邻两轮的差</b>。它不是你想要的那个误差 —— 而讲座完全没回答这个问题。");

clearScene();setEq(null);
setBig("ε 就是精度","设 ε = 0.01 就是结果精确到 0.01");
setCap("把<b>步长</b>当成<b>到终点的距离</b> —— 这是所有迭代算法共有的陷阱。");

clearScene();setBig(null);
setEq("$$\\lVert V_k - V^* \\rVert_\\infty \\;\\le\\; \\frac{\\gamma}{1-\\gamma}\\,\\lVert V_k - V_{k-1} \\rVert_\\infty$$","top");
lamps({y:320,gap:250,items:[
  {label:"γ=0.9",sub:"×9",state:"on"},
  {label:"γ=0.99",sub:"×99",state:"dead"},
  {label:"γ=0.999",sub:"×999",state:"dead"}]});
setCap("推导一行：剩余距离 = 未来所有增量之和，而 γ + γ² + ⋯ = γ/(1−γ)。<b>这个界讲座一次都没出现过</b>。");

clearScene();setBig(null);
setEq("$$\\gamma=0.9:\\quad \\text{停机于 } k=67$$","top");
fillBars({vals:[0.00955,0.08595],order:[0,1],step:800,
  x:330,y:430,w:620,h:170,max:0.09,
  label:function(i){return ["你看到的增量","真实误差"][i];},
  cls:function(i){return i===0?"b":"r";},
  fmt:function(v){return v.toFixed(5);}});
setCap("你以为误差 0.0096，实际 0.0860 —— <b>差 9 倍</b>。比值 0.08595/0.00955 = 9.00，正是 γ/(1−γ)，<b>界取到了等号</b>。");

clearScene();setBig(null);
setEq("$$\\gamma=0.99:\\quad \\text{停机于 } k=689$$","top");
fillBars({vals:[0.00993,0.98322],order:[0,1],step:800,
  x:330,y:430,w:620,h:170,max:1.0,
  label:function(i){return ["你看到的增量","真实误差"][i];},
  cls:function(i){return i===0?"b":"r";},
  fmt:function(v){return v.toFixed(5);}});
setCap("γ=0.99：你以为误差 0.0099，实际 <b>0.983</b>，<b>差 99 倍</b>。左边那根几乎看不见 —— 这正是它的问题。");

clearScene();setBig(null);
setEq("$$\\varepsilon \\;=\\; \\delta\\,\\frac{1-\\gamma}{\\gamma}$$","top");
lamps({y:320,gap:340,items:[
  {label:"γ=0.9, δ=0.01",sub:"ε = 1.11e−3",state:"on"},
  {label:"γ=0.99, δ=0.01",sub:"ε = 1.01e−4",state:"on"}]});
setCap("<b>指名反驳</b>：ε 是步长不是精度。顺带 —— 本例 γ=0.9 时<b>第 11 轮贪心策略已最优</b>，而值要到第 67 轮。");
